"use client"

import * as React from "react"

import { useInk } from "@/lib/ink/react"
import { inputRecipe } from "@/lib/ink/recipes/input-ink"
import { cn } from "@/lib/utils"

const controlClass =
  "h-full w-full min-w-0 flex-1 appearance-none border-0 bg-transparent px-3 py-1 text-sm text-foreground outline-none " +
  "placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-70 " +
  "file:border-0 file:bg-transparent file:text-sm file:font-medium " +
  "[&::-webkit-search-cancel-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none [&::-webkit-outer-spin-button]:appearance-none"

const frameClass =
  "relative isolate flex h-9 w-full min-w-0 items-center rounded-[var(--radius-md)] " +
  "caret-[var(--sd-caret)]"

function Input({
  className,
  type,
  seed,
  style,
  ref,
  ...props
}: React.ComponentProps<"input"> & { seed?: string | number }) {
  const invalid = props["aria-invalid"] === true || props["aria-invalid"] === "true"
  const { hostRef, hostProps, node } = useInk({
    recipe: inputRecipe,
    params: { disabled: !!props.disabled, invalid, readOnly: !!props.readOnly },
    kind: "field",
    seed,
    still: true,
  })

  if (type === "hidden") {
    return <input type="hidden" ref={ref} className={className} {...props} />
  }

  return (
    <span
      data-slot="input-frame"
      data-ink-focus="within"
      ref={hostRef}
      {...hostProps}
      style={style}
      className={cn(frameClass, className)}
    >
      {node}
      <input data-slot="input" type={type} ref={ref} className={controlClass} {...props} />
    </span>
  )
}

export { Input }

import { wash } from '@/lib/ink/fills'
import { roundRectPoly } from '@/lib/ink/geom'
import { box, focusRing } from '@/lib/ink/shapes'
import { clamp } from '@/lib/ink/rng'
import { defineRecipe } from '@/lib/ink/recipes'
import { softFill } from '@/lib/ink/recipes/wash-utils'

export interface InputParams {
  disabled?: boolean
  invalid?: boolean
  readOnly?: boolean
}

export const inputRecipe = defineRecipe<InputParams>({
  id: 'input',
  kind: 'field',
  layers: ['rest', 'hover', 'focus', 'disabled', 'invalid'],
  lazy: ['focus'],
  pad: 8,
  draw(ink, { w, h }, { disabled, invalid, readOnly }, ctx) {
    const r = clamp(h * 0.14, 3.5, 7)
    const inset = 0.55
    const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)

    if (disabled) {
      if (ctx.lazyOnly) return
      ink.layer('disabled', () => {
        wash(ink, body, 'sand-shade', { alpha: 0.48, wobble: 0.45, material: 'wash' })
        box(ink, 0.5, 0.5, w - 1, h - 1, {
          pen: 'pencil.fine',
          corner: r,
          loose: 0.35,
          opts: { alpha: 0.35, simple: true },
        })
      })
      return
    }

    if (invalid) {
      ink.layer('invalid', () => {
        softFill(ink, body, [
          { color: 'wash-rose', alpha: 0.35, wobble: 0.8 },
          { color: 'ember', alpha: 0.18, inset: 0.6 },
        ])
        box(ink, 0.55, 0.55, w - 1.1, h - 1.1, {
          pen: 'rose.fine',
          corner: r,
          loose: 1,
          opts: { alpha: 0.75, wobble: 0.4, simple: true, color: 'danger' },
        })
      })
    }

    ctx.lazy('focus', (fink) => {
      wash(fink, body, 'star', { alpha: 0.22, wobble: 0.6, material: 'wash', inset: 0.15 })
      wash(fink, body, 'horizon', { alpha: 0.12, wobble: 0.75, material: 'wash', inset: 1.2 })
      focusRing(fink, 0, 0, w, h, {
        r,
        pen: 'horizonPencil.fine',
        opts: { alpha: 0.9, wobble: 0.32, simple: true },
      })
    })
    if (ctx.lazyOnly) return

    ink.layer('rest', () => {
      softFill(ink, body, [
        { color: 'sand-slip', alpha: 0.72, wobble: 0.55 },
        { color: 'sand', alpha: 0.28, inset: 0.8 },
      ])
      box(ink, 0.55, 0.55, w - 1.1, h - 1.1, {
        pen: readOnly ? 'pencil.fine' : 'rose.fine',
        corner: r,
        loose: readOnly ? 0.5 : 0.95,
        opts: {
          alpha: readOnly ? 0.42 : 0.58,
          wobble: 0.36,
          simple: w < 120,
          color: readOnly ? 'pencil' : 'ink-soft',
        },
      })
    })

    ink.layer('hover', () => {
      if (readOnly) return
      wash(ink, body, 'rose-wash', { alpha: 0.28, wobble: 0.85, material: 'wash' })
      box(ink, 0.8, 0.8, w - 1.6, h - 1.6, {
        pen: 'ink.fine',
        corner: r,
        loose: 0.85,
        opts: { alpha: 0.4, simple: true, color: 'horizon' },
      })
    })
  },
})

import type { Ink } from '@/lib/ink/builder'
import type { Pt } from '@/lib/ink/types'
import type { PaintKey } from '@/lib/ink/paint'
import { wash } from '@/lib/ink/fills'

export function softFill(
  ink: Ink,
  body: Pt[],
  layers: Array<{ color: PaintKey; alpha: number; inset?: number; wobble?: number }>,
) {
  for (const layer of layers) {
    wash(ink, body, layer.color, {
      alpha: layer.alpha,
      inset: layer.inset ?? 0.4,
      wobble: layer.wobble ?? 0.95,
      material: 'wash',
    })
  }
}
